"use client";

import { useCallback, useState } from "react";
import { createMemo, errorMessage, type MemoRecord } from "@/lib/api";
import type { RunView } from "@/lib/types";

/** The review memo for the current run: generated by the API from its stored, verified findings. */
export function useMemoAction() {
  const [memo, setMemo] = useState<MemoRecord | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const generate = useCallback(async (run: RunView | null) => {
    if (!run || run.stage !== "complete") return;
    setBusy(true);
    setError(null);
    try {
      setMemo(await createMemo(run.id));
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }, []);

  const reset = useCallback(() => {
    setMemo(null);
    setError(null);
  }, []);

  return { memo, busy, error, generate, reset };
}

export type MemoController = ReturnType<typeof useMemoAction>;
